.fa-chevron-right {
  display: inline-block;
  width: 25px;
  height: 25px; 
  min-width: 0;
  opacity: 1 !important; 
  background: center/contain no-repeat;
opacity: 1 !important;

}

.fa-chevron-left {
  background-image: url('https://iili.io/B9jnB87.png'); /* 左 */
  margin-bottom: -72px; 

padding: 0px 0px 0;
}
