  color: #3c3847 !important;
font-family: "ChillHuoFangKai_F";
    font-weight: normal;
}
.swipes-counter {
  position: absolute;
  top: 60px;
  right: 66px;
  z-index: 9999;
  pointer-events: none;
}

/* ==============================================
🦋气泡拼接开始🦋 *==============================================*/



/* 🍃 中层气泡*/
.mes {
   z-index: -3;
  max-width: 425px;/*【🍃宽度】*/
  width: 100%;/*【👁宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 210px auto 40px;/*【AI和用户的气泡距离⭕️第一个是调整最早的消息与顶部的距离防止顶部超过屏幕】*/
  border-radius: 0px;
  background: #fff !important;
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  position: relative;
  overflow: visible;
  box-shadow: none !important; 
}

/* 🍃上层装饰层、拼接气泡顶部 */
.mes::before {
  content: "";
  position: absolute;
  top: -179px; /* 【上下】(负值向上) */
  left: 0%; /* 左右 */
  width: 483px; /* 【宽度/大小】 */
  height: 680px; /* 【高度/大小】 */
  background-image: url('https://iili.io/B9ZmfDv.png'); 
  background-size: contain; 
  background-repeat: no-repeat; 
  z-index: -2; 
  pointer-events: none; 
}

/* 🍃下层装饰层、拼接气泡尾部 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -150px; /* 【上下】(负值向下) */
  left: 0%; /* 左右 */
  width: 423px; /* 【宽度/大小】 */
  height: 202px; /* 【高度/大小👁会影响最新消息的底部留白，不可调太高，宽度拉不动再调高一点】 */
background-image: url(""); 
  background-size: contain; 
  background-repeat: no-repeat;
  z-index: -4; 
  pointer-events: none; 
}
/*——————🍃文本边距——————*/

 .mes_text,
.mes_reasoning {
    font-weight: 300; 
    line-height: 1.9; /* 行高 */
    text-align: justify; 
    text-justify: inter-word; 
    overflow-wrap: anywhere;
    hyphens: auto; 

    /* 优化后的间距系统 */
    --top-padding: 30rem;    /* 顶部 */
    --bottom-padding: 0rem; /* 底部 */
    --left-padding: 0rem;  /* 左侧 */
    --right-padding: 0.5rem; /* 右侧 */


    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);

    max-width: 100ch;

    margin: 0 auto; 

    /* 高级排版增强 */
    font-kerning: normal; 
    letter-spacing: 0.01em; 
    text-rendering: optimizeLegibility; 
}

.mes_reasoning::first-letter {
    font-weight: 600;
    margin-right: 0.5em;
}
/*@咩野老师lambkinling*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}



/* ==============================================
🦋气泡拼接结束🍃头像美化开始============================================== */


/*⭕️头像框*/
.mesAvatarWrapper {
  position: absolute;
  top: -147px;
  left: 48.9%;
  transform: translateX(-50%);
  z-index: -1;
  width: 70px;  
  height: 70px; 
  overflow: visible; 
}

/* ⭕️头像框位置与大小调整核心 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 113%;/* 【上下】 */
  left: 105%;/* 【左右】 */
  width: 360%;  /* 【框宽度】 */
  height: 312%; /* 【框高度】 */
  display: block;

  /* ⭕️头像框链接放置处 */
  background-image: url('');/*←🍃*/
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -50%);
  z-index: 1; 

}

.mesAvatarWrapper img {
  position: relative;
  z-index: -1; 
}

/* ⭕️头像位置 */
.mesAvatarWrapper {
  position: absolute;
  top: 20px;           /* 【负值向上】 */
  left: 15%;            /* 【头像左右】 */
  transform: translateX(-50%);
  z-index: -1;
    filter: 
    saturate(1) !important;
}

/* ⭕️头像尺寸*/
.mesAvatarWrapper .avatar {
  /* 🍃头像尺寸 */
  width: 107px;           /* 宽度 */
  height: 107px;          /* 高度 */
  transform: rotate(0deg); /* 旋转 */
}
.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ⭕user设置页面/角色选择头像美化⭕*/
/*收藏头像黄圈隐藏、名字颜色修改@Little YE*/
.character_select.is_fav .avatar {
  outline: none !important;
}
.character_select.is_fav .ch_name {
  color: #5f7186 !important;
}
.avatar img {
    border: 2px solid white; /* 头像描边 */
box-shadow:0px 0px 2px rgba(0, 0, 0, 0.4);
}
.avatar-container{
filter: 
    saturate(1) !important;}
.bogus_folder_select,
.character_select{
filter: 
    saturate(1) !important;}

/* ==============================================
🦋头像美化结束🍃文字效果美化开始============================================== */
/*去除提示词阴影@①点这里*/

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
filter: none;
}

/* === 设置选项=== */
small {
  color: #48383e !important;
  opacity: 1;

}
.toggle-description {
    color: #48383e;
}
.drawer-content .alignItemsBaseline, #UI-presets-block .alignitemscenter {
  color: #452f23; /* 设置下拉框旁文字 */
}
#completion_prompt_manager .completion_prompt_manager_header div {
    color: #48383e; /*字符*/
}

.fa-solid::before, .fa-regular::before {
    vertical-align: middle;
    text-align: center;
}

.right_menu_button {
    padding: 0px;
    filter: none;
    color: #b5a59d !important; /* 更新文字颜色 */
}

/*世界书激活时按钮颜色*/
.world_set, .toggleEnabled {
    color: #b5a59d !important;
}
/*角色收藏时按钮颜色*/
.fav_on {
    color: #b5a59d !important;
}
/* === 预设区文字颜色 === */
/* 选中 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #452f23;
}

/* 未选 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, 
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #b5a59d;
}

