#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: #b5a59d;
}

/* 代码块 */
code, pre {
  background: url('https://iili.io/B9GMwml.png') repeat-y !important;
background-size: 100% auto !important;
  color: #452f23 !important; 
  border: 2px solid #fff !important; 
box-shadow: 
  inset -1px 1px 0px rgba(0, 0, 0, 0.1),
inset 1px -1px 0px rgba(0, 0, 0, 0.1),
  0px 0px 2px rgba(0, 0, 0, 0.3);
  border-radius: 0px !important; 
line-height: 1.5; 
padding: 2px 7px;
}


code, pre {
  position: relative;
  overflow: visible !important;
}
/* 引用气泡 */
.mes_text q {
    background: linear-gradient(to bottom, 
    rgba(255, 255, 255, 0) 60%, 
    rgba(143, 201, 185, 0.2) 60%) !important; 
  padding-bottom: 0px;

  -webkit-box-decoration-break: clone;
border: 0px solid #ffffff !important;
box-shadow: 
    inset 0px 1px 0px rgba(255, 255, 255, 0), 
    0px 1px 0px rgba(81,1,1, 0) !important;
  border-radius: 0px 0px 0px 0px !important;
font-weight: 500;
line-height: 1.5;
padding: 3px 0px;
}


/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  border-left:2px solid #a9bdbb !important;
  background: linear-gradient(to right, rgba(255, 255, 255, 0.0) 0%, transparent 100%) !important;
  color: #452f23 !important; 
  box-shadow: 
    inset 2px -0px 2px rgba(0, 0, 0,0),
    -3px -3px 4px rgba(245, 189, 206, 0);
  border-radius: 0px !important; 

}
.mes_text blockquote,
.mes_reasoning blockquote {
    padding-left: 8px;
    padding-right: 10px;
}
/* 斜体 */
em, i {
  background: rgba(116, 88, 74, 0) !important;
box-shadow:0px 0px 5px rgba(0, 0, 0, 0);
}
/* ——自定义文本选中样式@时鸢 —— */
::selection {
    background-color: rgba(116, 88, 74, 0.9); 
    color: #fff;                 
    text-shadow: none;   
}

/* Firefox 兼容 */
::-moz-selection {
    background-color: rgba(116, 88, 74, 0.9); 
    color: #fff;
    text-shadow: none;
}

/* 输入框内的选中样式（可选） */
input::selection,
textarea::selection {
    background-color: rgba(116, 88, 74, 0.9); 
    color: #fff;
}
/* ==============================================
🦋文字效果美化结束🍃零碎美化开始============================================== */

/*—— 🍃楼层 ——*/


.mes .mesIDDisplay {
    position: fixed;
    top: 295px;
    left: 264px;                    /* 从左侧开始定位 */
  transform: none;            /* 移除所有变换效果 */
    z-index: 2;
    margin-top: 0px;
    text-align: center;           /* 文字左对齐 */
    width: auto;                /* 宽度自适应内容 */
    white-space: nowrap;        /* 防止文字换行 */
    padding: 0 10px;            /* 添加左右内边距 */
    display: inline-flex; 
    align-items: center;  
    gap: 2px;            /* 【左右文字间距】 */

    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 1.8);
    font-weight: 300;
    color: #74584a;      /* 【颜料🎨】【主文字颜色】 */
transform: rotate(0deg); /* 旋转 */


}




/*—— 🍃基础信息【时间戳、角色昵称等】 ——*/

/* ⭕️消息文字上边距留白核心调整 */
.mes_block {
  position: relative;
  margin-top: -120px;  
  overflow: visible;
}

/* ⭕️角色名称核心调整 */
.mes_block .ch_name {
  position: relative;
  top:170px; /* 上下 */
  left: 132px;
  max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 10; 
  font-size: 1.7em;
  font-weight: 300;
  letter-spacing: 0.9px;
  white-space: nowrap;
  transform: rotate(-0deg); /* 旋转 */
  color: #452f23 !important; 
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
}


/* ⭕️时间戳核心调整 */
.timestamp {
  position: absolute;
  top: 255px;                /* 上下 */
  left: 223px;                /* 左右 */
  width: 300%; 
  font-size: 0.95em;            /* 字体大小 */
  font-weight: 300;          /* 字体粗细 */
  transform: rotate(0deg);   /* 旋转 */
  white-space: nowrap;
  color: #7A7A7A !important; 
  opacity: 1 !important;
}




/* ⭕️编辑按钮核心调整 */
.mes_buttons {
  position: relative;
  top: 310px; /*上下*/
  left: -40px;/*左右*/
  z-index: 30;
  padding: 20px; 
  min-height: 36px;
  box-sizing: border-box;
  transform: rotate(0deg); /* 旋转 */
}

.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
    filter: none; /*移除阴影*/
    transition: 0.3s ease-in-out;

    /* ⭕编辑菜单位置核心调整⭕ */
    position: relative;
    top: 365px;  /* 负数上移 | 正数下移  */
    right: 130px;   /* 负数右移 | 正数左移  */

  transform: rotate(0deg); /* 旋转 */
}
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
}
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: none !important;
    /* ⭕设置省略号菜单颜色 */
    color: #74584a !important;
opacity: 0.7 !important; 
}

/*—— 计时器&字符——*/
.mes {
  position: relative; 
}

.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; 
  z-index: 3; 
  cursor: default;
opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 1.8);/*文字大小*/
  font-weight: 300;/*文字粗细*/
  padding: 0;
  top: var(--element-top, 240px);
  left: var(--element-left, 50%);
  transform: translateX(var(--element-translate, -50%));
transform: rotate(0deg); /* 旋转 */

}


/* === ⭕️计时器核心 === */
.mes .mes_timer {
  --element-top: var(--counter-top, 295px); /* 【🍃計時器计数器上下】 */
  --element-left: var(--counter-left, 42%); /* 【🍃计时器计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #74584a; /* 【🍃计时器颜色】 */
  color: var(--counter-main-color);
}



/* === 字符计数器单独设置 === */
.mes .tokenCounterDisplay {
  text-align: left;
  --element-top: var(--counter-top, 295px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 222%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #74584a; /* 【🍃计数器颜色】 */

  color: var(--counter-main-color);

}


