  background-image: url('https://iili.io/B9j3z11.png'); 
  background-size: contain;
  background-repeat: no-repeat;
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0));
  transition: all 0.3s ease;
  z-index: 1;
}
.mes_reasoning_header {
  position: absolute;
  z-index: 9999;
  top: 138px;/*思维链上下*/
  left: 31.7%;/思维左右*/
  transform: translateX(-50%);
  cursor: pointer;
  user-select: none;
  font-size: calc(var(--mainFontSize) * 0.75);
  transition: all 0.3s ease;
  padding: 0px 10px;
