/*————弹窗————*/
/*@hr*/
#toast-container > .toast {
    background-image: none !important;
    background: url('https://iili.io/B9GMwml.png') repeat-y !important;
background-size: 100% auto !important;

    border-radius: 0px ;
    border: 2px solid #fff !important;
  color: #3c3847; 
  box-shadow:
inset -1px 1px 0px rgba(0, 0, 0, 0.1),
inset 1px -1px 0px rgba(0, 0, 0, 0.1),
0px 0px 3px rgba(0, 0, 0, 0.2);
    opacity: 1 !important;    /* 设置透明度 */
    padding: 10px 15px 10px 50px; /* 调整内边距，上-右-下-左 */
    min-height: 30px;/* 通知框最小高度 */ 
    max-width: 260px;/* 通知框最大宽度 */
backdrop-filter: blur(0px) !important;

}
.toast::after {
    content: '';
    position: absolute;
    right: -5px;/* 右侧图标装饰*/
    bottom: -10px;/* 底部的位置 */
    width: 40px;/* 宽度 */
    height: 40px;/* 高度  */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

}
.toast::before {
    content: '';
    position: absolute;
    left: 3px;/* 设置图标距离左边的位置 */
    top: 50%;/* 垂直居中对齐 */
    transform: translateY(-50%);
    width: 37px;/* 宽度 */
    height: 37px;/* 高度 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
opacity: 1 !important;

}

/* 成功 (Success) 通知的自定义图标 */
